export const portalEnLegacy: PageDetail = {
  id: 110,
  title: "Financial Literacy Portal",
  slug: "financial-literacy-portal",
  content: "<p>The Financial Literacy portal (<a href=\"http://www.bizimpullar.az\">www.bizimpullar.az</a>) has been in use since 2015.</p>\n<p>The portal's main goal is to bring together all initiatives aimed at increasing financial literacy, such as resources and information about events, in one virtual space. At the same time, it aims to become the country's main promotional platform for financial literacy.</p>\n<p>Everyone can access the portal's resources, and registration is not required.</p>\n<p>To explain the main features of the portal, we have prepared informative videos (animations) that cover various topics. The modern audience, especially young people, prefers audio-visual materials to reading. These videos present important financial and banking concepts in a clear and accessible way to a wide range of population groups. Topics include \"What is a loan?\", \"What is a deposit?\", and \"Contactless cards.\" Each topic follows the principle of \"one question — one answer.\" These topics are presented to users in the \"Financial Services\" section of the portal.</p>\n<p>In addition to common financial and banking concepts, this portal also explains complex macroeconomic concepts such as \"policy interest rate,\" \"balance of payments,\" and \"inflation\" in simple language. These topics are posted in the Central Bank section of the portal.</p>\n<p>The \"Money\" section contains animations about updated paper money in circulation. It presents interesting and educational information about the images and security features on each denomination in video format.</p>\n<p>In addition to animations, the portal includes practical games. The \"Central Bank\" game simulator, in particular, has gained special popularity among users. This tool helps users understand the Central Bank's main role in the economy. Playing the role of the Central Bank, the game participant must maintain economic growth and inflation levels within a certain range by controlling the refinancing rate, a key monetary policy instrument. Several economic shocks are provided to make the game simulation more interesting and realistic.</p>\n<p>The \"News\" section contains information on various topics, including events, seminars, competitions, and the development of new financial literacy resources.</p>\n<p>Additionally, you can find interesting and useful information in other sections of the portal, such as the virtual museum, education, and calculators.</p>\n<p><a data-media-link=\"\" href=\"/media/1387\">1</a><a data-media-link=\"\" href=\"/media/1388\">2</a><a data-media-link=\"\" href=\"/media/1389\">3</a></p>",
  assets: [{"mediaId":1387,"title":"1","mimeType":"image/png","sizeBytes":2009,"group":null,"url":"/media/1387"},{"mediaId":1388,"title":"2","mimeType":"image/png","sizeBytes":2009,"group":null,"url":"/media/1388"},{"mediaId":1389,"title":"3","mimeType":"image/png","sizeBytes":2009,"group":null,"url":"/media/1389"}],
}

